import sys

def main():
    t = int(sys.stdin.readline())
    for _ in range(t):
        n, k = map(int, sys.stdin.readline().split())
        s = sys.stdin.readline().strip()
        count = 0
        i = 0
        while i < n:
            if s[i] == 'B':
                count += 1
                i += k
            else:
                i += 1
        print(count)

if __name__ == "__main__":
    main()
```

```python
import sys

def main():
    t = int(sys.stdin.readline())
    for _ in range(t):
        n, k = map(int, sys.stdin.readline().split())
        s = sys.stdin.readline().strip()
        b_positions = []
        for idx, char in enumerate(s):
            if char == 'B':
                b_positions.append(idx)
        if not b_positions:
            print(0)
            continue
        res = 0
        prev_end = -1
        i = 0
        while i < len(b_positions):
            current = b_positions[i]
            if current > prev_end:
                res += 1
                end = current + k - 1
                prev_end = end
                # Move i forward until we pass the current end
                while i < len(b_positions) and b_positions[i] <= end:
                    i += 1
            else:
                # Already covered, move to next
                i += 1
        print(res)

if __name__ == "__main__":
    main()
```

```python
import sys

def main():
    input = sys.stdin.read().split()
    ptr = 0
    t = int(input[ptr])
    ptr += 1
    for _ in range(t):
        n, k = map(int, input[ptr:ptr+2])
        ptr +=2
        a = list(map(int, input[ptr:ptr+n]))
        ptr +=n

        if k == 2:
            for num in a:
                if num % 2 == 0:
                    print(0)
                    break
            else:
                print(1)
        elif k == 3:
            for num in a:
                if num % 3 == 0:
                    print(0)
                    break
            else:
                min_step = float('inf')
                for num in a:
                    rem = num % 3
                    step = (3 - rem) % 3
                    if step < min_step:
                        min_step = step
                print(min_step)
        elif k == 4:
            # Calculate option_a: minimal steps to make any element divisible by 4
            option_a = float('inf')
            for num in a:
                rem = num % 4
                if rem == 0:
                    option_a = 0
                    break
                else:
                    step = (4 - rem) % 4
                    if step < option_a:
                        option_a = step
            # Calculate option_b: steps to have at least two even elements
            even_count = sum(1 for num in a if num % 2 == 0)
            if even_count >= 2:
                option_b = 0
            else:
                option_b = (2 - even_count)
            print(min(option_a, option_b))
        elif k == 5:
            # Similar to k=3
            for num in a:
                if num % 5 == 0:
                    print(0)
                    break
            else:
                min_step = float('inf')
                for num in a:
                    rem = num % 5
                    step = (5 - rem) % 5
                    if step < min_step:
                        min_step = step
                print(min_step)

if __name__ == "__main__":
    main()
```

```python
import sys

def main():
    input = sys.stdin.read().split()
    idx = 0
    t = int(input[idx])
    idx += 1
    for _ in range(t):
        n, k = map(int, input[idx:idx+2])
        idx +=2
        a = list(map(int, input[idx:idx+n]))
        idx +=n

        # Compute product mod k
        product_mod = 1
        divisible_by_k = False
        for num in a:
            mod = num % k
            product_mod = (product_mod * mod) % k
            if mod == 0:
                divisible_by_k = True
        if product_mod == 0 or divisible_by_k:
            print(0)
            continue

        if k == 2:
            # Check if any even number exists
            for num in a:
                if num % 2 == 0:
                    print(0)
                    break
            else:
                print(1)
        elif k == 3:
            # Find the minimal steps to reach a multiple of 3
            min_steps = float('inf')
            for num in a:
                rem = num % 3
                steps = (3 - rem) % 3
                if steps < min_steps:
                    min_steps = steps
            print(min_steps)
        elif k == 4:
            # According to earlier analysis, minimal steps is 1
            print(1)
        elif k == 5:
            # Find minimal steps to reach next multiple of 5
            min_steps = float('inf')
            for num in a:
                rem = num % 5
                steps = (5 - rem) % 5
                if steps < min_steps:
                    min_steps = steps
            print(min_steps)

if __name__ == "__main__":
    main()
```

```python
from typing import List

class Solution:
    def countSeniors(self, details: List[str]) -> int:
        count = 0
        for detail in details:
            # Extract the age from indices 11 to 12 (exclusive end at 13)
            age = int(detail[11:13])
            if age > 60:
                count += 1
        return count
```

```python
from typing import List

class Solution:
    def countSeniors(self, details: List[str]) -> int:
        count = 0
        for detail in details:
            # Extract the age part (characters at index 11 and 12)
            # e.g., "7522" -> "75"
            age = int(detail[11:13])
            if age > 60:
                count += 1
        return count
```

